CALL_LOG = "fetch_calls.jsonl"


def fetch(acct, day, page):
    key = "%s|%s" % (acct, day)
    if key not in DATA:
        raise ValueError("账户日不存在")
    page = int(page)
    if page < 1:
        raise ValueError("页号从一起")
    info = DATA[key]
    try:
        with open(CALL_LOG, "a", encoding="utf-8") as f:
            f.write(json.dumps({"acct": acct, "day": day,
                                "page": page}, ensure_ascii=False) + "\n")
    except OSError:
        pass
    start = (page - 1) * 20
    rows = info["rows"][start:start + 20]
    return {"rows": [list(r) for r in rows],
            "more": start + 20 < info["total"],
            "total": info["total"]}
